insert into public.modifier_options (group_id, name, price_delta, sort_order) select g.id, 'Bañadas', 0, 1 from public.modifier_groups g where g.name = 'Preparación' and not exists (select 1 from public.modifier_options mo where mo.group_id = g.id and mo.name = 'Bañadas');
insert into public.modifier_options (group_id, name, price_delta, sort_order) select g.id, 'Sin bañar o broster', 0, 2 from public.modifier_groups g where g.name = 'Preparación' and not exists (select 1 from public.modifier_options mo where mo.group_id = g.id and mo.name = 'Sin bañar o broster');
insert into public.product_modifier_groups (product_id, group_id, sort_order) select p.id, g.id, 1 from public.products p, public.modifier_groups g where g.name = 'Preparación' and p.slug in ('combo-1', 'combo-2', 'combo-3', 'combo-4', 'combo-5', 'combo-6', 'combo-7') on conflict do nothing;
